package com.suresh.lifeos;
import android.content.*;import android.database.*;import android.database.sqlite.*;import org.json.*;import java.time.*;import java.util.*;
public class Store extends SQLiteOpenHelper{
 private static Store I; public static synchronized Store get(Context c){if(I==null)I=new Store(c.getApplicationContext());return I;} private Store(Context c){super(c,"lifeos.db",null,2);} 
 public void onCreate(SQLiteDatabase d){
  d.execSQL("CREATE TABLE settings(k TEXT PRIMARY KEY,v TEXT NOT NULL)");
  d.execSQL("CREATE TABLE tasks(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT,category TEXT,days TEXT,start_min INTEGER,duration INTEGER,privacy TEXT,points INTEGER,penalty INTEGER,active INTEGER DEFAULT 1,calendar_sync INTEGER DEFAULT 0,notes TEXT)");
  d.execSQL("CREATE TABLE task_log(id INTEGER PRIMARY KEY AUTOINCREMENT,day TEXT,task_id INTEGER,status TEXT,reason TEXT,UNIQUE(day,task_id))");
  d.execSQL("CREATE TABLE medications(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,dose TEXT,timing TEXT,notes TEXT,active INTEGER DEFAULT 1)");
  d.execSQL("CREATE TABLE health(id INTEGER PRIMARY KEY AUTOINCREMENT,metric TEXT,value TEXT,unit TEXT,day TEXT,notes TEXT)");
  d.execSQL("CREATE TABLE recipes(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,cuisine TEXT,calories INTEGER,protein REAL,details TEXT,last_used TEXT,active INTEGER DEFAULT 1)");
  d.execSQL("CREATE TABLE workouts(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,phase INTEGER,dow INTEGER,duration INTEGER,details TEXT,requires_clearance INTEGER DEFAULT 0,active INTEGER DEFAULT 1)");
  d.execSQL("CREATE TABLE memories(id INTEGER PRIMARY KEY AUTOINCREMENT,day TEXT,title TEXT,note TEXT)");
  d.execSQL("CREATE TABLE projects(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,priority INTEGER,next_action TEXT,status TEXT DEFAULT 'ACTIVE')");
  d.execSQL("CREATE TABLE finance(id INTEGER PRIMARY KEY AUTOINCREMENT,day TEXT,type TEXT,category TEXT,amount REAL,note TEXT)");
  d.execSQL("CREATE TABLE penalties(id INTEGER PRIMARY KEY AUTOINCREMENT,day TEXT,reason TEXT,amount INTEGER,settled INTEGER DEFAULT 0)");
  d.execSQL("CREATE TABLE shopping(id INTEGER PRIMARY KEY AUTOINCREMENT,item TEXT,category TEXT,bought INTEGER DEFAULT 0)"); seed(d);
 }
 public void onUpgrade(SQLiteDatabase d,int o,int n){}
 private void seed(SQLiteDatabase d){set(d,"profile_name","Suresh");set(d,"strict_mode","true");set(d,"daily_penalty_cap","500");set(d,"weekly_penalty_cap","2000");set(d,"medical_clearance_hiit","false");set(d,"calendar_id","");set(d,"target_sleep","22:30");set(d,"target_wake","06:00");set(d,"eating_start","09:00");set(d,"eating_end","20:00");addTask(d,"Wake up","HEALTH","1,2,3,4,5,6,7",360,5,"PRIVATE",3,100,"Starter task — edit or import your private setup.");addTask(d,"Plan the day","MIND","1,2,3,4,5,6,7",375,15,"PRIVATE",3,100,"Starter task.");String[][] a={{"Eggs","Protein"},{"Chicken","Protein"},{"Fish","Protein"},{"Vegetables","Vegetables"},{"Fruit","Fruit"}};for(String[]x:a){ContentValues v=new ContentValues();v.put("item",x[0]);v.put("category",x[1]);d.insert("shopping",null,v);}}
 private void set(SQLiteDatabase d,String k,String v){ContentValues c=new ContentValues();c.put("k",k);c.put("v",v);d.insertWithOnConflict("settings",null,c,SQLiteDatabase.CONFLICT_REPLACE);} public void set(String k,String v){set(getWritableDatabase(),k,v);} public String get(String k,String def){try(Cursor c=getReadableDatabase().rawQuery("SELECT v FROM settings WHERE k=?",new String[]{k})){return c.moveToFirst()?c.getString(0):def;}}
 private void addTask(SQLiteDatabase d,String t,String cat,String days,int start,int dur,String priv,int pts,int pen,String notes){ContentValues v=new ContentValues();v.put("title",t);v.put("category",cat);v.put("days",days);v.put("start_min",start);v.put("duration",dur);v.put("privacy",priv);v.put("points",pts);v.put("penalty",pen);v.put("notes",notes);d.insert("tasks",null,v);} 
 public List<Map<String,String>> q(String sql,String...a){ArrayList<Map<String,String>>o=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery(sql,a)){String[] n=c.getColumnNames();while(c.moveToNext()){LinkedHashMap<String,String>m=new LinkedHashMap<>();for(int i=0;i<n.length;i++)m.put(n[i],c.isNull(i)?"":c.getString(i));o.add(m);}}return o;}
 public long insert(String table,ContentValues v){return getWritableDatabase().insert(table,null,v);} public void del(String table,long id){getWritableDatabase().delete(table,"id=?",new String[]{String.valueOf(id)});} public void update(String table,long id,ContentValues v){getWritableDatabase().update(table,v,"id=?",new String[]{String.valueOf(id)});} 
 public void logTask(long id,String status,String reason){ContentValues v=new ContentValues();v.put("day",LocalDate.now().toString());v.put("task_id",id);v.put("status",status);v.put("reason",reason);getWritableDatabase().insertWithOnConflict("task_log",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
 private static final String[] T={"settings","tasks","task_log","medications","health","recipes","workouts","memories","projects","finance","penalties","shopping"};
 public String exportJson()throws Exception{JSONObject root=new JSONObject();root.put("format","SureshLifeOS");root.put("version",2);root.put("exported_at",ZonedDateTime.now().toString());JSONObject data=new JSONObject();SQLiteDatabase d=getReadableDatabase();for(String t:T){JSONArray a=new JSONArray();try(Cursor c=d.rawQuery("SELECT * FROM "+t,null)){String[] cols=c.getColumnNames();while(c.moveToNext()){JSONObject r=new JSONObject();for(int i=0;i<cols.length;i++)r.put(cols[i],c.isNull(i)?JSONObject.NULL:c.getString(i));a.put(r);}}data.put(t,a);}root.put("data",data);return root.toString();}
 public void importJson(String json)throws Exception{JSONObject root=new JSONObject(json);if(!"SureshLifeOS".equals(root.optString("format")))throw new IllegalArgumentException("Invalid Life OS backup");JSONObject data=root.getJSONObject("data");SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{for(String t:T){if(!data.has(t))continue;d.delete(t,null,null);JSONArray a=data.getJSONArray(t);for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i);ContentValues v=new ContentValues();Iterator<String>it=r.keys();while(it.hasNext()){String k=it.next();Object o=r.get(k);if(o==JSONObject.NULL)v.putNull(k);else v.put(k,String.valueOf(o));}d.insert(t,null,v);}}d.setTransactionSuccessful();}finally{d.endTransaction();}}
}
